using System.Drawing;using System.Windows.Forms;
namespace LSE.AutoCADElectrical.Librarian;
public sealed class LibrarySettingsForm:Form{readonly AppSettings s=SettingsService.Load();readonly Dictionary<string,TextBox> boxes=new();readonly Dictionary<string,CheckBox> checks=new();
 public LibrarySettingsForm(){Text="LSE Librarian Settings";StartPosition=FormStartPosition.CenterParent;Size=new Size(1040,860);MinimumSize=new Size(800,600);var p=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=3,Padding=new Padding(12),AutoScroll=true};p.ColumnStyles.Add(new(SizeType.Absolute,250));p.ColumnStyles.Add(new(SizeType.Percent,100));p.ColumnStyles.Add(new(SizeType.Absolute,110));int r=0;
  Add(p,"LSE symbol library folder",nameof(s.SymbolLibraryFolder),s.SymbolLibraryFolder,r++,"folder");Add(p,"Stock (NFPA) symbol library folder",nameof(s.StockSymbolLibraryFolder),s.StockSymbolLibraryFolder,r++,"folder");Add(p,"LSE footprint library folder",nameof(s.FootprintLibraryFolder),s.FootprintLibraryFolder,r++,"folder");Add(p,"Stock (panel) footprint library folder",nameof(s.StockFootprintLibraryFolder),s.StockFootprintLibraryFolder,r++,"folder");Add(p,"User circuits folder",nameof(s.UserCircuitsFolder),s.UserCircuitsFolder,r++,"folder");
  Add(p,"Icon menu folder (dat MENU)",nameof(s.IconMenuFolder),s.IconMenuFolder,r++,"folder");Add(p,"Schematic icon menu file name",nameof(s.SchematicMenuFile),s.SchematicMenuFile,r++);Add(p,"Panel icon menu file name",nameof(s.PanelMenuFile),s.PanelMenuFile,r++);Add(p,"Images subfolder name",nameof(s.ImagesSubfolder),s.ImagesSubfolder,r++);
  Add(p,"Footprint lookup MDB",nameof(s.FootprintLookupPath),s.FootprintLookupPath,r++,"Access (*.mdb;*.accdb)|*.mdb;*.accdb");Add(p,"Catalog MDB (default_cat.mdb)",nameof(s.CatalogPath),s.CatalogPath,r++,"Access (*.mdb;*.accdb)|*.mdb;*.accdb");Add(p,"LSE parts catalog workbook (.xlsx)",nameof(s.NamingWorkbookPath),s.NamingWorkbookPath,r++,"Excel workbook (*.xlsx;*.xlsm)|*.xlsx;*.xlsm");Add(p,"Naming standard JSON (fallback snapshot)",nameof(s.NamingStandardPath),s.NamingStandardPath,r++,"JSON (*.json)|*.json");Add(p,"Catalog backup folder (blank = next to the catalog)",nameof(s.CatalogBackupFolder),s.CatalogBackupFolder,r++,"folder");Add(p,"Catalog column holding the LSE part number",nameof(s.LsePartColumn),s.LsePartColumn,r++);Add(p,"Library standard JSON",nameof(s.LibraryStandardPath),s.LibraryStandardPath,r++,"JSON (*.json)|*.json");Add(p,"Backup folder",nameof(s.BackupFolder),s.BackupFolder,r++,"folder");Add(p,"Reference project (.wdp)",nameof(s.ReferenceProjectPath),s.ReferenceProjectPath,r++,"AutoCAD Electrical project (*.wdp)|*.wdp");
  Add(p,"Icon size (pixels)",nameof(s.IconPixels),s.IconPixels.ToString(),r++);Add(p,"Default series (3 digits)",nameof(s.DefaultSeries),s.DefaultSeries,r++);
  Add(p,"Company standards JSON (catalog browser)",nameof(s.CompanyStandardsPath),s.CompanyStandardsPath,r++,"JSON (*.json)|*.json");Add(p,"Block attribute that receives the LSE part number",nameof(s.LsePartAttribute),s.LsePartAttribute,r++);
  Add(p,"Vault Explorer folder (optional, catalog checkout)",nameof(s.VaultExplorerPath),s.VaultExplorerPath,r++,"folder");Add(p,"Vault server",nameof(s.VaultServer),s.VaultServer,r++);Add(p,"Vault name",nameof(s.VaultName),s.VaultName,r++);Add(p,"Catalog path in Vault (blank = no Vault checkout)",nameof(s.CatalogVaultPath),s.CatalogVaultPath,r++);
  Check(p,"Register footprints in footprint_lookup.mdb by default",nameof(s.RegisterFootprintLookup),s.RegisterFootprintLookup,r++);Check(p,"Audit opens every drawing (slow, checks attributes)",nameof(s.DeepAudit),s.DeepAudit,r++);Check(p,"Audit also checks stock AutoCAD Electrical menu pages",nameof(s.AuditStockEntries),s.AuditStockEntries,r++);Check(p,"Offer a catalog record (default_cat.mdb) in the Librarian wizard",nameof(s.OfferCatalogRecord),s.OfferCatalogRecord,r++);Check(p,"Fill USER2 with the purchase description (Description + MPN) by default",nameof(s.PurchaseDescriptionInUser2),s.PurchaseDescriptionInUser2,r++);
  var info=new Label{Text="Settings file: "+SettingsService.SettingsPath,AutoSize=true,Anchor=AnchorStyles.Left};p.Controls.Add(info,0,r);p.SetColumnSpan(info,3);p.RowStyles.Add(new(SizeType.Absolute,30));r++;
  var buttons=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoSize=true,FlowDirection=FlowDirection.LeftToRight};buttons.Controls.Add(Button("Read library paths from project...",ReadProject));buttons.Controls.Add(Button("Test",Test));buttons.Controls.Add(Button("Save naming snapshot (JSON)",SaveSnapshot));buttons.Controls.Add(Button("Diagnostics",()=>MessageBox.Show(DiagnosticsService.BuildReport(),"LSE Librarian Diagnostics")));buttons.Controls.Add(Button("Save",Save));p.Controls.Add(buttons,0,r);p.SetColumnSpan(buttons,3);p.RowStyles.Add(new(SizeType.Absolute,52));Controls.Add(p);}
 static Button Button(string text,Action a){var b=new Button{Text=text,AutoSize=true,Height=36,Padding=new Padding(8,0,8,0)};b.Click+=(_,_)=>a();return b;}
 void Add(TableLayoutPanel p,string label,string key,string value,int row,string? browse=null){p.RowStyles.Add(new(SizeType.Absolute,40));p.Controls.Add(new Label{Text=label,AutoSize=true,Anchor=AnchorStyles.Left},0,row);var t=new TextBox{Text=value,Dock=DockStyle.Fill};boxes[key]=t;p.Controls.Add(t,1,row);if(browse is null)return;var b=new Button{Text="Browse",Dock=DockStyle.Fill};b.Click+=(_,_)=>{if(browse=="folder"){using var f=new FolderBrowserDialog{SelectedPath=Directory.Exists(t.Text)?t.Text:""};if(f.ShowDialog(this)==DialogResult.OK)t.Text=f.SelectedPath;}else{using var f=new OpenFileDialog{Filter=browse,FileName=t.Text,CheckFileExists=false};if(f.ShowDialog(this)==DialogResult.OK)t.Text=f.FileName;}};p.Controls.Add(b,2,row);}
 void Check(TableLayoutPanel p,string label,string key,bool value,int row){p.RowStyles.Add(new(SizeType.Absolute,32));var c=new CheckBox{Text=label,Checked=value,AutoSize=true,Anchor=AnchorStyles.Left};checks[key]=c;p.Controls.Add(c,1,row);p.SetColumnSpan(c,2);}
 void Collect(){s.SymbolLibraryFolder=T(nameof(s.SymbolLibraryFolder));s.StockSymbolLibraryFolder=T(nameof(s.StockSymbolLibraryFolder));s.FootprintLibraryFolder=T(nameof(s.FootprintLibraryFolder));s.StockFootprintLibraryFolder=T(nameof(s.StockFootprintLibraryFolder));s.UserCircuitsFolder=T(nameof(s.UserCircuitsFolder));s.IconMenuFolder=T(nameof(s.IconMenuFolder));s.SchematicMenuFile=T(nameof(s.SchematicMenuFile));s.PanelMenuFile=T(nameof(s.PanelMenuFile));s.ImagesSubfolder=T(nameof(s.ImagesSubfolder));
  s.FootprintLookupPath=T(nameof(s.FootprintLookupPath));s.CatalogPath=T(nameof(s.CatalogPath));s.LibraryStandardPath=T(nameof(s.LibraryStandardPath));s.BackupFolder=T(nameof(s.BackupFolder));s.ReferenceProjectPath=T(nameof(s.ReferenceProjectPath));s.DefaultSeries=NamingService.Series(T(nameof(s.DefaultSeries)));s.NamingWorkbookPath=T(nameof(s.NamingWorkbookPath));s.NamingStandardPath=T(nameof(s.NamingStandardPath));s.CatalogBackupFolder=T(nameof(s.CatalogBackupFolder));s.LsePartColumn=T(nameof(s.LsePartColumn)).ToUpperInvariant();if(s.LsePartColumn.Length==0)s.LsePartColumn="USER1";CatalogService.ValidateColumn(s.LsePartColumn);
  s.CompanyStandardsPath=T(nameof(s.CompanyStandardsPath));s.LsePartAttribute=T(nameof(s.LsePartAttribute)).ToUpperInvariant();if(s.LsePartAttribute.Length==0)s.LsePartAttribute="USER1";if(!System.Text.RegularExpressions.Regex.IsMatch(s.LsePartAttribute,@"^[A-Za-z_][A-Za-z0-9_]{0,254}$"))throw new InvalidOperationException("The block attribute name may only contain letters, digits and underscores.");
  s.VaultExplorerPath=T(nameof(s.VaultExplorerPath));s.VaultServer=T(nameof(s.VaultServer));s.VaultName=T(nameof(s.VaultName));s.CatalogVaultPath=T(nameof(s.CatalogVaultPath));if(s.CatalogVaultPath.Length>0&&(s.VaultServer.Length==0||s.VaultName.Length==0))throw new InvalidOperationException("Vault server and Vault name are required when a catalog path in Vault is set.");
  s.IconPixels=int.TryParse(T(nameof(s.IconPixels)),out int px)&&px>=16&&px<=1024?px:throw new InvalidOperationException("Icon size must be a whole number between 16 and 1024 pixels.");if(s.SchematicMenuFile.Length==0||s.PanelMenuFile.Length==0||s.ImagesSubfolder.Length==0)throw new InvalidOperationException("Icon menu file names and the images subfolder cannot be blank.");
  s.RegisterFootprintLookup=checks[nameof(s.RegisterFootprintLookup)].Checked;s.OfferCatalogRecord=checks[nameof(s.OfferCatalogRecord)].Checked;s.PurchaseDescriptionInUser2=checks[nameof(s.PurchaseDescriptionInUser2)].Checked;s.DeepAudit=checks[nameof(s.DeepAudit)].Checked;s.AuditStockEntries=checks[nameof(s.AuditStockEntries)].Checked;}
 string T(string key)=>boxes[key].Text.Trim();
 void Save(){try{Collect();SettingsService.Save(s);DialogResult=DialogResult.OK;Close();}catch(Exception ex){MessageBox.Show(this,ex.Message,"LSE Librarian Settings",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
 void ReadProject(){try{using var f=new OpenFileDialog{Title="Read library paths from an AutoCAD Electrical project",Filter="AutoCAD Electrical project (*.wdp)|*.wdp",FileName=T(nameof(s.ReferenceProjectPath))};if(f.ShowDialog(this)!=DialogResult.OK)return;var x=SettingsService.ApplyProject(s,f.FileName);boxes[nameof(s.SymbolLibraryFolder)].Text=s.SymbolLibraryFolder;boxes[nameof(s.StockSymbolLibraryFolder)].Text=s.StockSymbolLibraryFolder;boxes[nameof(s.FootprintLibraryFolder)].Text=s.FootprintLibraryFolder;boxes[nameof(s.StockFootprintLibraryFolder)].Text=s.StockFootprintLibraryFolder;boxes[nameof(s.IconMenuFolder)].Text=s.IconMenuFolder;boxes[nameof(s.SchematicMenuFile)].Text=s.SchematicMenuFile;boxes[nameof(s.PanelMenuFile)].Text=s.PanelMenuFile;boxes[nameof(s.ReferenceProjectPath)].Text=s.ReferenceProjectPath;MessageBox.Show(this,string.Join(Environment.NewLine,x)+Environment.NewLine+Environment.NewLine+"Press Save to keep these values.","Read from project");}catch(Exception ex){MessageBox.Show(this,ex.Message,"Read from project",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
 void Test(){var x=new List<string>();try{Collect();}catch(Exception ex){x.Add("Settings: FAIL "+ex.Message);}
  foreach(var (n,p) in new[]{("Symbol library",s.SymbolLibraryFolder),("Footprint library",s.FootprintLibraryFolder),("User circuits",s.UserCircuitsFolder),("Icon menu folder",s.IconMenuFolder),("Images folder",s.ImagesFolder)})x.Add(n+": "+(Directory.Exists(p)?"PASS":"MISSING "+p));
  foreach(var (n,p) in new[]{("Schematic icon menu",s.SchematicMenuPath),("Panel icon menu",s.PanelMenuPath)})try{var m=IconMenuService.Load(p);x.Add($"{n}: PASS ({m.Pages.Count} pages)");}catch(Exception ex){x.Add(n+": FAIL "+ex.Message);}
  try{var std=LibraryStandardService.Load(s.LibraryStandardPath);x.Add($"Library standard: PASS ({std.Kinds.Count} kinds)");}catch(Exception ex){x.Add("Library standard: FAIL "+ex.Message);}
  try{x.Add($"Footprint lookup: PASS ({new FootprintLookupService(s.FootprintLookupPath).GetTables().Count} manufacturer tables)");}catch(Exception ex){x.Add("Footprint lookup: FAIL "+ex.Message);}
  try{var n=NamingWorkbookService.Load(s);x.Add((n.FromWorkbook?"Parts catalog workbook: PASS (":"Naming standard JSON snapshot (workbook not found): PASS (")+NamingWorkbookService.Describe(n)+")");}catch(Exception ex){x.Add("Naming standard: FAIL "+ex.Message);}
  try{x.Add($"Catalog: PASS ({new CatalogService(s.CatalogPath).GetTables().Count} family tables, part number column {CatalogTransactionService.PartColumn(s)}, backups in {CatalogTransactionService.BackupRoot(s)})");}catch(Exception ex){x.Add("Catalog: FAIL "+ex.Message);}
  x.Add("Company standards JSON: "+(File.Exists(s.CompanyStandardsPath)?$"PASS ({CompanyStandardsService.Load(s.CompanyStandardsPath).Count} records)":"not created yet (written on the first Toggle company standard)"));
  x.Add(VaultCatalogService.Enabled(s)?"Catalog Vault checkout: ON; Vault Explorer folder "+(Directory.Exists(s.VaultExplorerPath)?"PASS":"MISSING "+s.VaultExplorerPath):"Catalog Vault checkout: off");
  MessageBox.Show(this,string.Join(Environment.NewLine,x),"Settings test");}
 // Parses the workbook and writes the JSON snapshot, for workstations that cannot reach the workbook.
 void SaveSnapshot(){try{Collect();if(!File.Exists(s.NamingWorkbookPath))throw new FileNotFoundException("The parts catalog workbook was not found.",s.NamingWorkbookPath);var n=NamingWorkbookService.LoadWorkbook(s.NamingWorkbookPath,true);try{n.FamilyHints=new CatalogService(s.CatalogPath).FamilyHints(n.Format);}catch{}n.Source=Path.GetFileName(s.NamingWorkbookPath)+$" (snapshot {DateTime.Now:yyyy-MM-dd HH:mm} by {Environment.UserName})";NamingWorkbookService.SaveJson(n,s.NamingStandardPath);MessageBox.Show(this,"Snapshot written: "+s.NamingStandardPath+Environment.NewLine+NamingWorkbookService.Describe(n),"Naming snapshot");}catch(Exception ex){MessageBox.Show(this,ex.Message,"Naming snapshot",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
}
